import numpy as np,itertools
L=[l.split() for l in open('answer.xyz').read().split('\n')[2:] if l.strip()]
A=[(x[0],np.array(list(map(float,x[1:4])))) for x in L]
r={'H':0.37,'C':0.77,'P':1.1,'Si':1.17,'Ru':1.4}
nb={i:[] for i in range(len(A))}
for i,j in itertools.combinations(range(len(A)),2):
    d=np.linalg.norm(A[i][1]-A[j][1])
    if d< (r[A[i][0]]+r[A[j][0]])*1.25: nb[i].append(j); nb[j].append(i)
for i,(e,p) in enumerate(A):
    if e!='H': print(i,e,[A[j][0] for j in nb[i]])
